message.content:
{
  "css": ".trip-footer {
  margin-top: 24px;
}

.trip-footer button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 56px;
  padding: 0 24px;
  margin: 0 -24px;
  background-color: #bdbdbd;
  color: #ffffff;
  font-family: "Noto Sans KR", sans-serif;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  border-radius: 12px;
  border: none;
  cursor: default;
}

.trip-footer button:disabled {
  opacity: 1;
}"
}
